// @FIGURE_CODE_BEGIN
(function () {
  var NAVY = '#1F3864', RED = '#c0392b', BLUE = '#2471c9', ORANGE = '#e8820c';
  var FAM = 'DejaVu Sans, Verdana, Helvetica, sans-serif';
  var VX = [-2.28, 4.28], VY = [-2.22, 2.22];
  var CH0 = { x: 0, y: 0 }, CH1 = { x: 2, y: 0 };
  var MSAT = 6.0;

  var container = document.getElementById('container');
  var draw = SVG().addTo(container).size('100%', '100%');
  var gAxes = draw.group();      // frame + ticks + tick labels + axis titles (cleared every layout)
  var gLines = draw.group();
  var gArrows = draw.group();
  var gMark = draw.group();
  var gHit = draw.group();
  var gOverlay = draw.group();
  var gLegend = draw.group();
  gOverlay.attr('pointer-events', 'none');
  gLegend.attr('pointer-events', 'none');
  gMark.attr('pointer-events', 'none');

  var mode = 'Vector grid', gridN = 25;
  var S = 400, bx = 50, by = 10, ux = 60, uy = 90, fs = 11, sw = 0.9;
  var spPx = 15, Lmax = 14;
  var samples = [], fieldLines = [], hoverSample = null, pinned = null;

  /* ---------- physics ---------- */
  function fieldAt(x, y) {
    var ax = x - CH0.x, ay = y - CH0.y, r0 = Math.sqrt(ax * ax + ay * ay);
    var cx = x - CH1.x, cy = y - CH1.y, r1 = Math.sqrt(cx * cx + cy * cy);
    var p0 = r0 > 1e-4 ? 1 / (r0 * r0 * r0) : 0;
    var p1 = r1 > 1e-4 ? 1 / (r1 * r1 * r1) : 0;
    return {
      ex: ax * p0 - cx * p1, ey: ay * p0 - cy * p1,
      px: ax * p0, py: ay * p0,
      nx: -cx * p1, ny: -cy * p1,
      m0: r0 > 1e-4 ? 1 / (r0 * r0) : 0,
      m1: r1 > 1e-4 ? 1 / (r1 * r1) : 0
    };
  }
  function unitDir(p) {
    var f = fieldAt(p.x, p.y), m = Math.hypot(f.ex, f.ey);
    if (!(m > 0) || !isFinite(m)) return null;
    return { x: f.ex / m, y: f.ey / m };
  }
  function rk4(p, h) {
    var k1 = unitDir(p); if (!k1) return null;
    var k2 = unitDir({ x: p.x + h / 2 * k1.x, y: p.y + h / 2 * k1.y }); if (!k2) return null;
    var k3 = unitDir({ x: p.x + h / 2 * k2.x, y: p.y + h / 2 * k2.y }); if (!k3) return null;
    var k4 = unitDir({ x: p.x + h * k3.x, y: p.y + h * k3.y }); if (!k4) return null;
    return { x: h / 6 * (k1.x + 2 * k2.x + 2 * k3.x + k4.x), y: h / 6 * (k1.y + 2 * k2.y + 2 * k3.y + k4.y) };
  }
  function computeLines() {
    fieldLines = [];
    var n = 14, h = 0.015;
    for (var k = 0; k < n; k++) {
      var a = k * 2 * Math.PI / n;
      var p = { x: 0.055 * Math.cos(a), y: 0.055 * Math.sin(a) };
      var pts = [[0, 0], [p.x, p.y]];
      for (var s = 0; s < 5200; s++) {
        var d = rk4(p, h); if (!d) break;
        p = { x: p.x + d.x, y: p.y + d.y };
        if (Math.hypot(p.x - CH1.x, p.y - CH1.y) < 0.055) { pts.push([CH1.x, CH1.y]); break; }
        if (s % 3 === 0) pts.push([p.x, p.y]);
        if (Math.abs(p.x) > 12 || Math.abs(p.y) > 12) break;
      }
      fieldLines.push(pts);
    }
  }

  /* ---------- small helpers ---------- */
  function plain(g, str, x, y, size, color, anchor, baseline, bold) {
    var t = g.plain(str).font({ family: FAM, size: size, anchor: anchor || 'start', weight: bold ? 'bold' : 'normal' }).fill(color);
    t.attr({ x: x, y: y, 'dominant-baseline': baseline || 'auto' });
    return t;
  }
  function halo(t) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': Math.max(2, fs * 0.28), 'stroke-linejoin': 'round' });
    return t;
  }
  function headPath(x, y, dx, dy, hl) {
    var hw = hl * 0.66, ax = x - dx * hl, ay = y - dy * hl;
    return 'M' + x.toFixed(1) + ' ' + y.toFixed(1) +
      'L' + (ax - dy * hw / 2).toFixed(1) + ' ' + (ay + dx * hw / 2).toFixed(1) +
      'L' + (ax + dy * hw / 2).toFixed(1) + ' ' + (ay - dx * hw / 2).toFixed(1) + 'Z';
  }
  function dotPath(x, y, r) {
    var r2 = (2 * r).toFixed(2), rr = r.toFixed(2);
    return 'M' + (x - r).toFixed(1) + ' ' + y.toFixed(1) +
      'a' + rr + ' ' + rr + ' 0 1 0 ' + r2 + ' 0' +
      'a' + rr + ' ' + rr + ' 0 1 0 -' + r2 + ' 0Z';
  }
  function vecArrow(g, x, y, vx, vy, color, width, opacity, dashed) {
    var L = Math.hypot(vx, vy); if (L < 1.2) return;
    var dx = vx / L, dy = vy / L;
    var hl = Math.min(0.40 * L, Math.max(4.5, width * 3.2));
    var ln = g.line(x, y, x + dx * (L - hl * 0.7), y + dy * (L - hl * 0.7))
      .stroke({ color: color, width: width, linecap: 'round', opacity: opacity == null ? 1 : opacity });
    if (dashed) ln.attr('stroke-dasharray', '4,3');
    g.path(headPath(x + dx * L, y + dy * L, dx, dy, hl)).fill({ color: color, opacity: opacity == null ? 1 : opacity });
  }
  function fmt(v) {
    if (!isFinite(v)) return '—';
    if (v >= 100 || (v > 0 && v < 0.01)) return v.toExponential(1);
    return v.toFixed(2);
  }

  /* ---------- layout ---------- */
  function layout() {
    var cs = getComputedStyle(container);
    var W = Math.max(140, container.clientWidth - (parseFloat(cs.paddingLeft) || 0) - (parseFloat(cs.paddingRight) || 0));
    var H = Math.max(140, container.clientHeight - (parseFloat(cs.paddingTop) || 0) - (parseFloat(cs.paddingBottom) || 0));
    var base = Math.min(W, H);
    var mL = Math.max(28, base * 0.13), mB = Math.max(26, base * 0.125);
    var mT = base * 0.03, mR = base * 0.035;
    var availW = Math.max(40, W - mL - mR), availH = Math.max(40, H - mT - mB);
    S = Math.max(60, Math.min(availW, availH));
    bx = mL + Math.max(0, (availW - S) / 2);
    by = mT + Math.max(0, (availH - S) / 2);
    ux = S / (VX[1] - VX[0]); uy = S / (VY[1] - VY[0]);
    var xd0 = VX[0] - bx / ux, xd1 = xd0 + W / ux;
    var yd0 = VY[1] - (H - by) / uy, yd1 = yd0 + H / uy;
    setPlotFrame({ xDomain: [xd0, xd1], yDomain: [yd0, yd1], margin: 0, draw: draw });
    fs = Math.max(6.5, S / 38);
    sw = Math.max(0.6, S / 490);
    drawAll();
  }

  /* ---------- axes (fully rebuilt each call — titles included) ---------- */
  function drawAxes() {
    gAxes.clear();
    gAxes.rect(S, S).move(bx, by).fill('#ffffff').stroke({ color: '#000', width: Math.max(0.8, S / 520) });
    var tl = Math.max(3, S / 115), tw = Math.max(0.7, S / 560);
    var t;
    for (t = -2; t <= 4; t++) {
      var px = plotX(t);
      gAxes.line(px, by + S, px, by + S + tl).stroke({ color: '#000', width: tw });
      plain(gAxes, (t < 0 ? '\u2212' : '') + Math.abs(t), px, by + S + tl + fs * 0.95, fs, '#000', 'middle');
    }
    for (t = -2; t <= 2; t++) {
      var py = plotY(t);
      gAxes.line(bx, py, bx - tl, py).stroke({ color: '#000', width: tw });
      plain(gAxes, (t < 0 ? '\u2212' : '') + Math.abs(t), bx - tl - fs * 0.35, py, fs, '#000', 'end', 'middle');
    }
    var xt = gAxes.text(function (add) {
      add.tspan('x').font({ style: 'italic' });
      add.tspan(' (m)');
    }).font({ family: FAM, size: fs * 1.18, weight: 'bold', anchor: 'middle' }).fill('#000');
    xt.attr({ x: bx + S / 2, y: by + S + tl + fs * 2.85, 'dominant-baseline': 'auto' });
    var yt = gAxes.text(function (add) {
      add.tspan('y').font({ style: 'italic' });
      add.tspan(' (m)');
    }).font({ family: FAM, size: fs * 1.18, weight: 'bold', anchor: 'middle' }).fill('#000');
    yt.attr({ x: 0, y: 0, 'dominant-baseline': 'central' });
    yt.attr('transform', 'translate(' + (bx - tl - fs * 2.5).toFixed(1) + ',' + (by + S / 2).toFixed(1) + ') rotate(-90)');
  }

  /* ---------- vector grid ---------- */
  function computeSamples() {
    samples = [];
    // Column spacing chosen so x = 0 and x = 2 are exact sample columns;
    // row spacing chosen so the grid is square in pixels.
    var targetD = (VX[1] - VX[0]) / gridN;
    var k = Math.max(1, Math.round(2 / targetD));
    var dxw = 2 / k;
    var dyw = dxw * ux / uy;
    spPx = dxw * ux;
    Lmax = Math.min(0.95 * spPx, 0.55 * ux);
    var i0 = Math.ceil((VX[0] + 0.035) / dxw), i1 = Math.floor((VX[1] - 0.035) / dxw);
    var j0 = Math.ceil((VY[0] + 0.035) / dyw), j1 = Math.floor((VY[1] - 0.035) / dyw);
    for (var i = i0; i <= i1; i++) {
      var wx = i * dxw;
      for (var j = j0; j <= j1; j++) {
        var wy = j * dyw;
        var r0 = Math.hypot(wx - CH0.x, wy - CH0.y), r1 = Math.hypot(wx - CH1.x, wy - CH1.y);
        if (r0 < 1e-3 || r1 < 1e-3) continue;          // exactly on a charge
        var f = fieldAt(wx, wy);
        var vx = f.ex * ux, vy = -f.ey * uy;
        var dl = Math.hypot(vx, vy);
        if (!(dl > 0) || !isFinite(dl)) continue;
        var m = Math.hypot(f.ex, f.ey);
        samples.push({
          wx: wx, wy: wy, x: plotX(wx), y: plotY(wy),
          dx: vx / dl, dy: vy / dl, f: f, m: m,
          L: Lmax * Math.pow(Math.min(1, m / MSAT), 0.45)
        });
      }
    }
  }
  function drawArrows() {
    gArrows.clear();
    if (mode === 'Field lines') return;
    var shafts = '', heads = '', dots = '';
    var w = Math.max(0.6, S / 520);
    var op = (mode === 'Both overlaid') ? 0.42 : 1;
    var dr = Math.max(0.42, Math.min(1.1, spPx * 0.055));
    var thresh = Math.max(3.0, spPx * 0.26);
    for (var k = 0; k < samples.length; k++) {
      var s = samples[k], L = s.L;
      if (L < thresh) { dots += dotPath(s.x, s.y, dr); continue; }
      var hl = Math.min(0.44 * L, Math.max(2.6, w * 3.4));
      var ex = s.x + s.dx * (L - hl * 0.72), ey = s.y + s.dy * (L - hl * 0.72);
      shafts += 'M' + s.x.toFixed(1) + ' ' + s.y.toFixed(1) + 'L' + ex.toFixed(1) + ' ' + ey.toFixed(1);
      heads += headPath(s.x + s.dx * L, s.y + s.dy * L, s.dx, s.dy, hl);
    }
    if (dots) gArrows.path(dots).fill({ color: NAVY, opacity: op * 0.85 }).stroke('none');
    if (shafts) gArrows.path(shafts).fill('none').stroke({ color: NAVY, width: w, linecap: 'round', linejoin: 'round', opacity: op });
    if (heads) gArrows.path(heads).fill(NAVY).stroke('none').opacity(op);
  }

  /* ---------- field lines ---------- */
  function drawLines() {
    gLines.clear();
    if (mode === 'Vector grid') return;
    var lw = Math.max(0.7, S / 430);
    var interval = Math.max(26, S * 0.1);
    var heads = '';
    function emit(seg) {
      if (seg.length < 2) return;
      var str = '';
      for (var i = 0; i < seg.length; i++) str += (i ? ' ' : '') + seg[i][0].toFixed(1) + ',' + seg[i][1].toFixed(1);
      gLines.polyline(str).fill('none').stroke({ color: NAVY, width: lw, linecap: 'round', linejoin: 'round', opacity: 0.95 });
    }
    for (var k = 0; k < fieldLines.length; k++) {
      var pts = fieldLines[k], seg = [], acc = 0, last = null;
      for (var i = 0; i < pts.length; i++) {
        var w = pts[i];
        var inside = w[0] >= VX[0] && w[0] <= VX[1] && w[1] >= VY[0] && w[1] <= VY[1];
        if (!inside) { emit(seg); seg = []; last = null; acc = 0; continue; }
        var P = [plotX(w[0]), plotY(w[1])];
        if (last) {
          var dd = Math.hypot(P[0] - last[0], P[1] - last[1]);
          acc += dd;
          if (acc > interval && dd > 0.01) {
            acc = 0;
            heads += headPath(P[0], P[1], (P[0] - last[0]) / dd, (P[1] - last[1]) / dd, Math.max(3.2, S / 95));
          }
        }
        last = P; seg.push(P);
      }
      emit(seg);
    }
    if (heads) gLines.path(heads).fill(NAVY).stroke('none');
  }

  /* ---------- charge markers + legend ---------- */
  function drawMarks() {
    gMark.clear();
    var show = (mode !== 'Vector grid') || !!(hoverSample || pinned);
    if (!show) return;
    var r = Math.max(4, fs * 0.6);
    function mk(wx, wy, sym, col, tip) {
      var g = gMark.group();
      g.circle(r * 2).center(plotX(wx), plotY(wy)).fill('#fff').stroke({ color: col, width: Math.max(0.8, sw) }).opacity(0.85);
      plain(g, sym, plotX(wx), plotY(wy) + 0.5, fs * 1.12, col, 'middle', 'middle', true).opacity(0.95);
      g.attr('pointer-events', 'all').css('cursor', 'pointer');
      g.on('mousemove', function (e) { showTooltip(tip, e); }).on('mouseleave', hideTooltip);
      return g;
    }
    gMark.attr('pointer-events', 'none');
    mk(CH0.x, CH0.y, '+', RED, 'Positive charge +q at (0, 0): field points away from it');
    mk(CH1.x, CH1.y, '\u2212', BLUE, 'Negative charge \u2212q at (2, 0): field points toward it');
  }
  function drawLegend() {
    gLegend.clear();
    if (mode === 'Vector grid' && !(hoverSample || pinned)) return;
    var x = bx + S - fs * 0.6, y = by + fs * 1.2;
    var items = ['+q at (0, 0)', '\u2212q at (2, 0)'];
    if (mode !== 'Field lines') items.push('arrow length \u221d |E|');
    for (var i = 0; i < items.length; i++) {
      halo(plain(gLegend, items[i], x, y + i * fs * 1.35, fs * 0.82, '#33415c', 'end', 'middle'));
    }
  }

  /* ---------- hover overlay ---------- */
  function refreshOverlay() {
    var s = hoverSample || pinned;
    gOverlay.clear();
    drawMarks(); drawLegend();
    if (!s) return;
    var f = s.f;
    var A = { x: f.px * ux, y: -f.py * uy };
    var B = { x: f.nx * ux, y: -f.ny * uy };
    var R = { x: A.x + B.x, y: A.y + B.y };
    var maxPx = Math.max(22, 0.85 * ux);
    var big = Math.max(Math.hypot(A.x, A.y), Math.hypot(B.x, B.y), Math.hypot(R.x, R.y));
    var kk = big > 0 ? maxPx / big : 0;
    A = { x: A.x * kk, y: A.y * kk }; B = { x: B.x * kk, y: B.y * kk };
    R = { x: A.x + B.x, y: A.y + B.y };
    var P = { x: s.x, y: s.y };
    gOverlay.polygon([[P.x, P.y], [P.x + A.x, P.y + A.y], [P.x + R.x, P.y + R.y], [P.x + B.x, P.y + B.y]])
      .fill('none').stroke({ color: '#8a8a8a', width: Math.max(0.6, sw * 0.8), linejoin: 'round' })
      .attr('stroke-dasharray', '4,3').opacity(0.9);
    vecArrow(gOverlay, P.x, P.y, A.x, A.y, RED, Math.max(1.1, sw * 1.5), 0.92);
    vecArrow(gOverlay, P.x, P.y, B.x, B.y, BLUE, Math.max(1.1, sw * 1.5), 0.92);
    vecArrow(gOverlay, P.x, P.y, R.x, R.y, ORANGE, Math.max(1.6, sw * 2.4), 1);
    gOverlay.circle(Math.max(3.4, sw * 4)).center(P.x, P.y).fill('#fff').stroke({ color: ORANGE, width: Math.max(0.8, sw) });

    // readout card
    var cf = Math.max(6, fs * 0.82), lh = cf * 1.45;
    var rows = [
      ['point  (' + s.wx.toFixed(2) + ', ' + s.wy.toFixed(2) + ')', '#333'],
      ['from +q   ' + fmt(f.m0), RED],
      ['toward \u2212q   ' + fmt(f.m1), BLUE],
      ['total |E|   ' + fmt(s.m), ORANGE]
    ];
    var cw = Math.max(92, cf * 11.5), ch = rows.length * lh + cf * 1.1;
    var cx = P.x + 16, cy = P.y + 14;
    if (cx + cw > bx + S - 3) cx = P.x - 16 - cw;
    if (cy + ch > by + S - 3) cy = P.y - 14 - ch;
    cx = Math.min(Math.max(cx, bx + 3), bx + S - cw - 3);
    cy = Math.min(Math.max(cy, by + 3), by + S - ch - 3);
    var card = gOverlay.group();
    card.rect(cw, ch).move(cx, cy).radius(3).fill({ color: '#ffffff', opacity: 0.94 })
      .stroke({ color: '#b9c0cc', width: 0.8 });
    for (var i = 0; i < rows.length; i++) {
      var ty = cy + cf * 0.9 + i * lh;
      if (i > 0) card.rect(cf * 0.62, cf * 0.62).move(cx + cf * 0.55, ty - cf * 0.32).fill(rows[i][1]);
      plain(card, rows[i][0], cx + cf * 0.55 + (i > 0 ? cf * 1.25 : 0), ty, cf, rows[i][1], 'start', 'middle');
    }
  }
  function nearestSample(mx, my) {
    var best = null, bd = 1e18;
    for (var i = 0; i < samples.length; i++) {
      var d = (samples[i].x - mx) * (samples[i].x - mx) + (samples[i].y - my) * (samples[i].y - my);
      if (d < bd) { bd = d; best = samples[i]; }
    }
    return best;
  }
  function nearestSampleWorld(wx, wy) {
    var best = null, bd = 1e18;
    for (var i = 0; i < samples.length; i++) {
      var d = (samples[i].wx - wx) * (samples[i].wx - wx) + (samples[i].wy - wy) * (samples[i].wy - wy);
      if (d < bd) { bd = d; best = samples[i]; }
    }
    return best;
  }
  function updateHit() {
    gHit.clear();
    var r = gHit.rect(S, S).move(bx, by).fill('#fff').opacity(0).attr('pointer-events', 'all').css('cursor', 'crosshair');
    r.on('mousemove', function (e) {
      var rect = draw.node.getBoundingClientRect();
      var s = nearestSample(e.clientX - rect.left, e.clientY - rect.top);
      if (s) { hoverSample = s; refreshOverlay(); }
    });
    r.on('mouseleave', function () { hoverSample = null; refreshOverlay(); hideTooltip(); });
    r.on('click', function () {
      var s = hoverSample || pinned; if (!s) return;
      showPopup('Superposition at (' + s.wx.toFixed(2) + ', ' + s.wy.toFixed(2) + ')',
        'The single navy arrow drawn here is not a primitive object: it is E\u208A + E\u208B. The red arrow points directly away from +q at (0,0) with magnitude ' +
        fmt(s.f.m0) + ', the blue arrow points directly toward \u2212q at (2,0) with magnitude ' + fmt(s.f.m1) +
        ', and the dashed parallelogram closes onto the orange resultant of magnitude ' + fmt(s.m) +
        ' (arbitrary units, each contribution \u221d 1/r\u00B2). Field lines are simply these same resultants joined tangentially.');
    });
  }

  /* ---------- draw all ---------- */
  function drawAll() {
    drawAxes();
    drawLines();
    computeSamples();
    drawArrows();
    updateHit();
    refreshOverlay();
  }

  /* ---------- interactions ---------- */
  window.toggle_representation = function (v) {
    mode = v;
    drawLines(); drawArrows(); refreshOverlay();
  };
  window.update_gridDensity = function (v) {
    gridN = Math.max(4, Math.round(v));
    var pw = pinned ? { x: pinned.wx, y: pinned.wy } : null;
    computeSamples();
    if (pw) pinned = nearestSampleWorld(pw.x, pw.y);
    hoverSample = null;
    drawArrows(); refreshOverlay();
  };

  /* ---------- demo steps ---------- */
  var steps = [
    { title: 'The raw vector grid', narration: 'Hundreds of arrows on a square grid show the field everywhere at once. Two hot spots sit on y = 0: arrows fly outward from (0,0) and pile inward at (2,0), while everything far away fades to dots.', state: { representation: 'Vector grid', gridDensity: 25 } },
    { title: 'Thin the sampling', narration: 'Drop to a coarse grid. The arrows are fewer and easier to read, yet the outward-then-inward dipole pattern is unchanged — the clutter came from how densely we sampled, not from the field itself.', state: { representation: 'Vector grid', gridDensity: 9 } },
    { title: 'One point, two contributions', narration: 'Hover any arrow. Two component arrows appear — one pointing away from the positive charge at (0,0), one pointing toward the negative charge at (2,0) — and their sum is exactly the arrow that was already drawn there.', state: { representation: 'Vector grid', gridDensity: 15 } },
    { title: 'Connect the arrows into lines', narration: 'Now link arrows tip-to-tail into continuous curves. Every line starts on the positive charge and ends on the negative charge, and the crowding of lines near the charges replaces arrow length as the magnitude cue.', state: { representation: 'Field lines', gridDensity: 15 } },
    { title: 'Same field, two pictures', narration: 'With both overlaid, every arrow lies tangent to a field line. The two representations are the same information; field lines simply say it with far less ink.', state: { representation: 'Both overlaid', gridDensity: 15 } }
  ];
  var curStep = 0;
  function applyStep(i) {
    curStep = (i + steps.length) % steps.length;
    var st = steps[curStep];
    document.getElementById('representationInput').value = st.state.representation;
    document.getElementById('gridDensityInput').value = st.state.gridDensity;
    document.getElementById('gridDensityVal').value = st.state.gridDensity;
    mode = st.state.representation;
    gridN = st.state.gridDensity;
    pinned = null; hoverSample = null;
    computeSamples();
    if (curStep === 2) pinned = nearestSampleWorld(1.0, 0.62);
    drawLines(); drawArrows(); refreshOverlay();
    document.getElementById('demoNarration').textContent = st.narration;
    document.getElementById('stepLabel').textContent = (curStep + 1) + '/' + steps.length + ' · ' + st.title;
  }
  window.nextStep = function () { applyStep(curStep + 1); };
  window.prevStep = function () { applyStep(curStep - 1); };

  /* ---------- init ---------- */
  computeLines();
  layout();
  document.addEventListener('fig-resize', function () {
    var pw = pinned ? { x: pinned.wx, y: pinned.wy } : null;
    hoverSample = null; pinned = null;
    layout();
    if (pw) { pinned = nearestSampleWorld(pw.x, pw.y); refreshOverlay(); }
  });
  document.getElementById('demoNarration').textContent = steps[0].narration;
  document.getElementById('stepLabel').textContent = '1/' + steps.length + ' · ' + steps[0].title;

  window.__markRendered();
})();
